+static enum ft_result
+string_to_uinteger64(const fvalue_t *src, guint64 *dst)
+{
+	int base = 0;
+	const char *s;
+	char *endptr;
+	guint64 res;
+
+	s = src->value.strbuf->str;
+
+	if (s[0] == '0' && (s[1] == 'b' || s[1] == 'B')) {
+		base = 2;
+	}
+
+	errno = 0;
+	res = g_ascii_strtoull(s, &endptr, base);
+	if (errno == ERANGE)
+		return FT_OVERFLOW;
+	if (errno != 0)
+		return FT_ERROR;
+	if (endptr == s)
+		return FT_BADARG;
+
+	*dst = res;
+	return FT_OK;
+}
